pub(crate) fn push_entity40_where(
    qb: &mut sqlx::QueryBuilder<'_, sqlx::Postgres>,
    w: &crate::m_09_stress::Entity40WhereInput,
) -> bool {
    let mut any = false;
    if let Some(f) = &w.id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_filter(qb, "id", f);
    }
    if let Some(f) = &w.field_1 {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "field_1", f);
    }
    if let Some(group) = &w.and {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("(");
            if !push_entity40_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    if let Some(group) = &w.or {
        if any {
            qb.push(" AND ");
        }
        any = true;
        qb.push("(");
        let mut first = true;
        for sub in group {
            if !first {
                qb.push(" OR ");
            }
            first = false;
            qb.push("(");
            if !push_entity40_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
        qb.push(")");
    }
    if let Some(group) = &w.not {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT (");
            if !push_entity40_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    any
}

